<?php
require __DIR__.'/config.php';require_login();
mysqli_query($conn,"CREATE TABLE IF NOT EXISTS pesan_tamu (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,nama VARCHAR(100) NOT NULL,pesan TEXT NOT NULL,dibuat DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP)");
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$nama=trim($_POST['nama']??'');$pesan=trim($_POST['pesan']??'');if($nama!==''&&$pesan!==''){$s=mysqli_prepare($conn,"INSERT INTO pesan_tamu(user_id,nama,pesan) VALUES(?,?,?)");mysqli_stmt_bind_param($s,'iss',$_SESSION['user_id'],$nama,$pesan);mysqli_stmt_execute($s);mysqli_stmt_close($s);}header('Location:buku_tamu.php');exit;}
$hasil=mysqli_query($conn,"SELECT * FROM pesan_tamu ORDER BY id DESC LIMIT 20");
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Buku Tamu</title></head><body><main><h1>◉ Buku Tamu</h1><form method="post"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input name="nama" placeholder="Nama" required><textarea name="pesan" placeholder="Pesan" required></textarea><button>Kirim</button></form><hr><?php while($row=mysqli_fetch_assoc($hasil)):?><article><strong><?=h($row['nama'])?></strong><small> <?=h($row['dibuat'])?></small><p><?=h($row['pesan'])?></p></article><hr><?php endwhile;?><a href="pentest.php">Pentest Lab</a> · <a href="index.php">Beranda</a></main></body></html>